```ts
export interface CpuPoint { t: number; v: number | null }
export class CpuStore {
  static WINDOW = 24 * 60 * 60 * 1000;
  static STEP = 1000;
  timeline: number[] = [];
  values: (number|null)[] = [];
  private listeners = new Set<() => void>();
