```tsx
import {useEffect, useRef} from 'react';
import Yagr from 'yagr';
import type {MinimalValidConfig} from 'yagr';
import 'yagr/dist/index.css';
import {cpuStore} from './cpuStore';

const LINE_COLOR = {light: '#4776e6', dark: '#5e8ef5'} as const;

export function CpuLoadChart({theme}: {theme: 'light' | 'dark'}) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const yagrRef = useRef<Yagr | null>(null);

  // create / recreate on theme change
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const yagr = new Yagr(root, buildConfig(theme));
    yagrRef.current = yagr;
    return () => {
      yagrRef.current = null;
      yagr.dispose();
    };
  }, [theme]);

  // live stream
  useEffect(() => {
    const unsub = cpuStore.subscribe(({timeline, values}) => {
      const y = yagrRef.current;
      if (!y) return;
      const data = y.uplot.data as unknown as [number[], (number | null)[]];
      data[0].push(...timeline);
      data[1].push(...values);
      const overflow = data[0].length - MAX...; // store already trimmed; but chart copies also need trim
      y.uplot.setData(data, false);
    });
    cpuStore.start();
    return () => { unsub(); cpuStore.stop(); };
  }, []);
```

Trimming: store trims its own arrays; chart's copies grow unboundedly. Trim chart arrays too: keep last MAX_POINTS: if data[0].length > MAX, splice from front by the amount appended (timeline.length) → keeps aligned with store. Since store trimmed exactly the same number, splice(0, timeline.length) works when at max. Simpler: `const extra = data[0].length - MAX_POINTS; if (extra > 0) { data[0].splice(0, extra); data[1].splice(0, extra); }`.

Edge: setData(data, false) — uPlot's setData second arg resetScales=false keeps zoom. But when not zoomed, auto scale re-fits to data — window slides, fine.

One issue: x scale min/max when not zoomed — auto to data min/max → sliding window works.

