mkdir -p /tmp/shots && cat > /tmp/shots/shot.mjs <<'EOF'
import {chromium} from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 800}});
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));

await page.goto('http://localhost:5199/', {waitUntil: 'networkidle'});
await page.waitForSelector('.cpu-load-chart canvas', {timeout: 15000});
await page.waitForTimeout(3000); // дать живым тикам поработать
await page.screenshot({path: '/tmp/shots/light.png'});

// переключаем тему
await page.getByRole('button', {name: /тёмную тему/}).click();
await page.waitForTimeout(1500);
await page.screenshot({path: '/tmp/shots/dark.png'});

// зум выделением
const chart = await page.locator('.cpu-load-chart .u-over').boundingBox();
if (chart) {
  await page.mouse.move(chart.x + chart.width * 0.3, chart.y + chart.height / 2);
  await page.mouse.down();
  await page.mouse.move(chart.x + chart.width * 0.55, chart.y + chart.height / 2, {steps: 10});
  await page.mouse.up();
  await page.waitForTimeout(800);
  await page.screenshot({path: '/tmp/shots/zoom.png'});
